pm.test("Non-Existing room returns 404", function (){
    pm.response.to.have.status(404);
});

pm.test("Room has a room ID", function(){
    const response = pm.response.json();
    pm.expect(response.roomid || response.roomid).to.exist;
});

pm.test("Room ID is a positive integer", function(){
    const response  = pm.response.json();
    pm.expect(response.roomid).to.be.a("number");
    pm.expect(Number.isInteger(response.roomid)).to.eql(true);
    pm.expect(response.roomid).to.be.greaterThan(0);
});

pm.test("Returned room ID matches the requested ID", function(){
    const response = pm.response.json();
    pm.expect(response.roomid).to.eql(1);
});

pm.test("Room has all required fields", function(){
    const response = pm.response.json();
    pm.expect(response).to.have.property("roomid");
    pm.expect(response).to.have.property("roomName");
    pm.expect(response).to.have.property("roomPrice");
    pm.expect(response).to.have.property("type");
});

pm.test("Room price is  positive number", function(){
    const response = pm.response.json();
    pm.expect(response.roomPrice).to.be.a("number");
    pm.expect(response.roomPrice).to.be.greaterThan(0);
});

pm.test("Error response includes the correct path", function(){
    const response = pm.response.json();
    pm.expect(response.path).to.eql("/room/4");
});

